# Python Simulation: Waterfall Monetization vs Unified Header Bidding Economics
class MonetizationModelSimulator:
    def __init__(self):
        # 5 competing programmatic demand partners with distinct valuations for an impression
        self.demand_sources = [
            {"name": "AdNetwork-Alpha", "tier": 1, "historical_avg_cpm": 2.50, "current_bid": 2.20},
            {"name": "AdNetwork-Beta",  "tier": 2, "historical_avg_cpm": 4.00, "current_bid": 3.50},
            {"name": "SSP-Gamma",       "tier": 3, "historical_avg_cpm": 3.00, "current_bid": 1.80},
            {"name": "SSP-Delta",       "tier": 4, "historical_avg_cpm": 5.00, "current_bid": 8.90}, # Whale buyer!
            {"name": "AdNetwork-Epsilon","tier": 5, "historical_avg_cpm": 1.50, "current_bid": 1.20}
        ]

    def simulate_legacy_waterfall(self) -> dict:
        latency_per_hop_ms = 450 # Latency penalty of sequential passback
        accumulated_latency = 0

        # Waterfall evaluates strictly by pre-assigned historical tier
        sorted_tiers = sorted(self.demand_sources, key=lambda x: x["tier"])
        for source in sorted_tiers:
            accumulated_latency += latency_per_hop_ms
            # Tier 1 floor is $3.00, Tier 2 floor is $3.00
            if source["tier"] == 1 and source["current_bid"] >= 3.00:
                return {"winner": source["name"], "cleared_cpm": source["current_bid"], "latency_ms": accumulated_latency}
            if source["tier"] == 2 and source["current_bid"] >= 3.00:
                # Tier 2 fills at $3.50, terminating the waterfall before Tier 4 is even called!
                return {"winner": source["name"], "cleared_cpm": source["current_bid"], "latency_ms": accumulated_latency}

        return {"winner": "Passback-Unsold", "cleared_cpm": 0.0, "latency_ms": accumulated_latency}

    def simulate_unified_header_bidding(self, wrapper_timeout_ms: int = 800) -> dict:
        # Header bidding executes all bids asynchronously in parallel
        # Max latency is bounded strictly by the wrapper timeout threshold
        parallel_latency = min(320, wrapper_timeout_ms) # Fastest network response time

        # True unified first-price auction: highest bid wins regardless of tier
        highest_bidder = max(self.demand_sources, key=lambda x: x["current_bid"])
        return {
            "winner": highest_bidder["name"],
            "cleared_cpm": highest_bidder["current_bid"],
            "latency_ms": parallel_latency,
            "unlocked_surplus": highest_bidder["current_bid"] - 3.50 # Surplus over waterfall
        }

sim = MonetizationModelSimulator()
waterfall_res = sim.simulate_legacy_waterfall()
hb_res = sim.simulate_unified_header_bidding()

print("=== WATERFALL VS HEADER BIDDING MONETIZATION BENCHMARK ===")
print(f"Legacy Waterfall Clearing: Winner = {waterfall_res['winner']} | Cleared = ${waterfall_res['cleared_cpm']:.2f} CPM | Latency = {waterfall_res['latency_ms']} ms")
print(f"Header Bidding Clearing:   Winner = {hb_res['winner']} | Cleared = ${hb_res['cleared_cpm']:.2f} CPM | Latency = {hb_res['latency_ms']} ms")
print(f"Publisher Economic Gain: +${hb_res['unlocked_surplus']:.2f} CPM ({hb_res['cleared_cpm'] / waterfall_res['cleared_cpm'] * 100 - 100:.1f}% Yield Increase)")
print(f"Latency Optimization:    Saved {waterfall_res['latency_ms'] - hb_res['latency_ms']} ms of browser render blocking time!")

// TypeScript Simulation: Prebid.js Wrapper Engine & Lifecycle Orchestration
interface AdUnitConfig {
  code: string; // DOM element ID
  mediaTypes: { banner?: { sizes: number[][] }; video?: { playerSize: number[] } };
  bids: Array<{ bidder: string; params: Record<string, any> }>;
}

interface PrebidBid {
  bidder: string;
  adUnitCode: string;
  cpm: number;
  width: number;
  height: number;
  adId: string;
  timeToRespondMs: number;
}

class MockPrebidWrapper {
  private adUnits: AdUnitConfig[] = [];
  private bidderTimeoutMs: number = 800; // 800ms strict timeout
  private targetingKeyValues: Record<string, Record<string, string>> = {};

  public addAdUnits(units: AdUnitConfig[]) {
    this.adUnits = units;
    console.log(`[Prebid.js] Registered ${units.length} ad unit(s) for bidding.`);
  }

  public setConfig(config: { bidderTimeout?: number }) {
    if (config.bidderTimeout) self.bidderTimeoutMs = config.bidderTimeout;
  }

  public async requestBids(): Promise<Record<string, PrebidBid>> {
    console.log(`[Prebid.js] Starting auction with bidderTimeout = ${this.bidderTimeoutMs}ms...`);
    const winningBids: Record<string, PrebidBid> = {};

    for (const unit of this.adUnits) {
      console.log(`\n--- Requesting bids for slot: '${unit.code}' ---`);

      // Simulate parallel async HTTP calls to bidder adapters
      const bidPromises = unit.bids.map(b => this.mockBidderAdapter(b.bidder, unit.code));
      const responses = await Promise.all(bidPromises);

      // Filter out timed-out bids and sort descending by CPM
      const validBids = responses
        .filter(b => b.timeToRespondMs <= this.bidderTimeoutMs)
        .sort((a, b) => b.cpm - a.cpm);

      if (validBids.length > 0) {
        const winner = validBids[0];
        winningBids[unit.code] = winner;
        console.log(`  🏆 Slot Winner: ${winner.bidder} ($${winner.cpm.toFixed(2)} CPM in ${winner.timeToRespondMs}ms)`);
      } else {
        console.log(`  🚨 All bids timed out on slot '${unit.code}'!`);
      }
    }

    this.setTargetingForGPT(winningBids);
    return winningBids;
  }

  private async mockBidderAdapter(bidder: string, adUnitCode: string): Promise<PrebidBid> {
    // Simulate network latency and varying valuation
    const latencies: Record<string, number> = { rubicon: 310, appnexus: 420, pubmatic: 610, slow_bidder: 950 };
    const bids: Record<string, number> = { rubicon: 4.85, appnexus: 5.20, pubmatic: 3.90, slow_bidder: 7.50 };

    const latency = latencies[bidder] || 400;
    const cpm = bids[bidder] || 2.00;

    return {
      bidder,
      adUnitCode,
      cpm,
      width: 300,
      height: 250,
      adId: `ad_${Math.random().toString(36).substring(2, 8)}`,
      timeToRespondMs: latency
    };
  }

  private setTargetingForGPT(winningBids: Record<string, PrebidBid>) {
    for (const [slotCode, bid] of Object.entries(winningBids)) {
      // Format price bucket: standard 10-cent rounding
      const priceBucket = (Math.floor(bid.cpm * 10) / 10).toFixed(2);
      this.targetingKeyValues[slotCode] = {
        hb_bidder: bid.bidder,
        hb_adid: bid.adId,
        hb_pb: priceBucket,
        hb_size: `${bid.width}x${bid.height}`
      };
    }
  }

  public getTargeting(): Record<string, Record<string, string>> {
    return this.targetingKeyValues;
  }
}

// Run Simulation
async function run() {
  const pbjs = new MockPrebidWrapper();
  pbjs.addAdUnits([{
    code: 'div-gpt-ad-top-leaderboard',
    mediaTypes: { banner: { sizes: [[728, 90], [970, 250]] } },
    bids: [
      { bidder: 'rubicon', params: { accountId: '1001' } },
      { bidder: 'appnexus', params: { placementId: '2002' } },
      { bidder: 'pubmatic', params: { publisherId: '3003' } },
      { bidder: 'slow_bidder', params: { zoneId: '4004' } }
    ]
  }]);

  await pbjs.requestBids();
  const gptTargeting = pbjs.getTargeting();

  console.log('\n=== GOOGLE PUBLISHER TAG (GPT) TARGETING KEY-VALUES ===');
  console.log(JSON.stringify(gptTargeting, null, 2));
  console.log('Notice: slow_bidder submitted $7.50 CPM but took 950ms (>800ms timeout) so was dropped!');
}
run();
